"""Limit order book with price-time priority and partial fills."""


class OrderNotFound(KeyError):
    pass


class Book:
    def __init__(self):
        # price -> deque of order ids (oldest first)
        self._bids = {}
        self._asks = {}
        # id -> [side, price, qty]
        self._orders = {}

    # -- public API -------------------------------------------------------

    def submit(self, order):
        """Submit order=(id, side, price, qty).

        Matches against the best opposite price while crossed; ties at the
        same price fill oldest-first. Remainder rests on the book.
        Returns a list of trades: (maker_id, taker_id, price, qty),
        executed at the RESTING order's price.
        """
        oid, side, price, qty = order
        side = self._norm_side(side)
        if oid in self._orders:
            raise ValueError(f"duplicate order id: {oid}")
        self._orders[oid] = [side, price, qty]
        trades = []
        while qty > 0:
            opp_price = self._best_opposite(side)
            if opp_price is None or not self._crosses(side, price, opp_price):
                break
            opp_book = self._asks if side == "buy" else self._bids
            queue = opp_book[opp_price]
            maker_id = self._front(queue)
            m_side, m_price, m_qty = self._orders[maker_id]
            fill = min(qty, m_qty)
            trades.append((maker_id, oid, m_price, fill))
            qty -= fill
            m_qty -= fill
            if m_qty == 0:
                queue.popleft()
                del self._orders[maker_id]
            else:
                self._orders[maker_id][2] = m_qty
        if qty > 0:
            own_book = self._bids if side == "buy" else self._asks
            own_book.setdefault(price, deque()).append(oid)
            self._orders[oid][2] = qty
        else:
            del self._orders[oid]
        return trades

    def cancel(self, oid):
        """Remove remaining quantity of order `oid`. Returns True if removed."""
        entry = self._orders.pop(oid, None)
        if entry is None:
            return False
        return True

    def open_orders(self):
        """Snapshot of resting orders: list of (id, side, price, qty)."""
        return [
            (oid, e[0], e[1], e[2]) for oid, e in self._orders.items()
        ]

    def best_bid(self):
        prices = [p for p, q in self._bids.items() if q]
        return max(prices) if prices else None

    def best_ask(self):
        prices = [p for p, q in self._asks.items() if q]
        return min(prices) if prices else None

    def resting_qty(self, oid):
        e = self._orders.get(oid)
        return None if e is None else e[2]

    # -- internals ---------------------------------------------------------

    @staticmethod
    def _norm_side(side):
        s = str(side).lower()
        if s in ("buy", "bid", "b"):
            return "buy"
        if s in ("sell", "ask", "s"):
            return "sell"
        raise ValueError(f"bad side: {side!r}")

    def _best_opposite(self, side):
        return self.best_ask() if side == "buy" else self.best_bid()

    @staticmethod
    def _crosses(side, price, opp_price):
        return price >= opp_price if side == "buy" else price <= opp_price

    def _front(self, queue):
        """Oldest live order at this price level (skips cancelled ids)."""
        while queue:
            maker_id = queue[0]
            if maker_id in self._orders:
                return maker_id
            queue.popleft()
        raise AssertionError("empty price level")


